def is_enharmonic(note1, note2):
    """Test whether note1 and note2 are enharmonic, i.e. they sound the same."""
    return note_to_int(note1) == note_to_int(note2)

def is_valid_note(note):
    """Return True if note is in a recognised format. False if not."""
    if note[0] not in _note_dict:
        return False
    for post in note[1:]:
        if post != "b" and post != "#":
            return False
    return True

def note_to_int(note):
    """Convert notes in the form of C, C#, Cb, C##, etc. to an integer in the
    range of 0-11.

    Throw a NoteFormatError exception if the note format is not recognised.
    """
    if is_valid_note(note):
        val = _note_dict[note[0]]
    else:
        raise NoteFormatError("Unknown note format '%s'" % note)

    # Check for '#' and 'b' postfixes
    for post in note[1:]:
        if post == "b":
            val -= 1
        elif post == "#":
            val += 1
    return val % 12

def reduce_accidentals(note):
    """Reduce any extra accidentals to proper notes.

    Example:
    >>> reduce_accidentals('C####')
    'E'
    """
    val = note_to_int(note[0])
    for token in note[1:]:
        if token == "b":
            val -= 1
        elif token == "#":
            val += 1
        else:
            raise NoteFormatError("Unknown note format '%s'" % note)
    if val >= note_to_int(note[0]):
        return int_to_note(val % 12)
    else:
        return int_to_note(val % 12, "b")

def is_valid_key(key):
    """Return True if key is in a recognized format. False if not."""
    for couple in keys:
        if key in couple:
            return True
    return False

def get_key_signature(key="C"):
    """Return the key signature.

    0 for C or a, negative numbers for flat key signatures, positive numbers
    for sharp key signatures.
    """
    if not is_valid_key(key):
        raise NoteFormatError("unrecognized format for key '%s'" % key)

    for couple in keys:
        if key in couple:
            accidentals = keys.index(couple) - 7
            return accidentals

def get_key_signature_accidentals(key="C"):
    """Return the list of accidentals present into the key signature."""
    from mingus.core import notes
    accidentals = get_key_signature(key)
    res = []

    if accidentals < 0:
        for i in range(-accidentals):
            res.append("{0}{1}".format(list(reversed(notes.fifths))[i], "b"))
    elif accidentals > 0:
        for i in range(accidentals):
            res.append("{0}{1}".format(notes.fifths[i], "#"))
    return res

def __init__(self, key="C"):
    self.key = key

    if self.key[0].islower():
        self.mode = "minor"
    else:
        self.mode = "major"

    try:
        symbol = self.key[1]
        if symbol == "#":
            symbol = "sharp "
        else:
            symbol = "flat "
    except:
        symbol = ""
    self.name = "{0} {1}{2}".format(self.key[0].upper(), symbol, self.mode)

    self.signature = get_key_signature(self.key)

def relative_major(key):
    """Return the relative major of a minor key.

    Example:
    >>> relative_major('a')
    'C'
    """
    for couple in keys:
        if key == couple[1]:
            return couple[0]
    raise NoteFormatError("'%s' is not a minor key" % key)

def relative_minor(key):
    """Return the relative minor of a major key.

    Example:
    >>> relative_minor('C')
    'a'
    """
    for couple in keys:
        if key == couple[0]:
            return couple[1]
    raise NoteFormatError("'%s' is not a major key" % key)

