def follow(string, next, name, prev=-1):
    """Follow the fret 'next' on 'string'; build result on the way."""
    if string >= len(self.tuning) - 1:
        return [[(next, name)]]
    result = []
    cur = res[string][next]
    if cur != []:
        for y in cur[1]:
            for sub in follow(string + 1, y[0], y[1]):
                if prev < 0:
                    result.append([(next, name)] + sub)
                else:
                    if sub[0][0] == 0 or abs(sub[0][0] - prev) < max_distance:
                        result.append([(next, name)] + sub)
    for s in follow(string + 1, maxfret + 1, None, next):
        result.append([(next, name)] + s)
    return [[(next, name)]] if result == [] else result

def make_lookup_table():
    """Prepare the lookup table.

    table[string][fret] = (name, dest_frets)
    """
    res = [
        [[] for x in range(maxfret + 2)] for x in range(len(self.tuning) - 1)
    ]
    for x in range(0, len(self.tuning) - 1):
        addedNone = -1
        next = fretdict[x + 1]
        for (fret, name) in fretdict[x]:
            for (f2, n2) in next:
                if n2 != name and (f2 == 0 or abs(fret - f2) < max_distance):
                    if res[x][fret] != []:
                        res[x][fret][1].append((f2, n2))
                    else:
                        res[x][fret] = (name, [(f2, n2)])
                if addedNone < x:
                    if res[x][maxfret + 1] != []:
                        res[x][maxfret + 1][1].append((f2, n2))
                    else:
                        res[x][maxfret + 1] = (None, [(f2, n2)])
            addedNone = x
    return res

def determine(chord, shorthand=False, no_inversions=False, no_polychords=False):
    """Name a chord.

    This function can determine almost every chord, from a simple triad to a
    fourteen note polychord."""
    if chord == []:
        return []
    elif len(chord) == 1:
        return chord
    elif len(chord) == 2:
        return [intervals.determine(chord[0], chord[1])]
    elif len(chord) == 3:
        return determine_triad(chord, shorthand, no_inversions, no_polychords)
    elif len(chord) == 4:
        return determine_seventh(chord, shorthand, no_inversions, no_polychords)
    elif len(chord) == 5:
        return determine_extended_chord5(chord, shorthand, no_inversions, no_polychords)
    elif len(chord) == 6:
        return determine_extended_chord6(chord, shorthand, no_inversions, no_polychords)
    elif len(chord) == 7:
        return determine_extended_chord7(chord, shorthand, no_inversions, no_polychords)
    else:
        return determine_polychords(chord, shorthand)

def determine_triad(triad, shorthand=False, no_inversions=False, placeholder=None):
    """Name the triad; return answers in a list.

    The third argument should not be given. If shorthand is True the answers
    will be in abbreviated form.

    This function can determine major, minor, diminished and suspended
    triads. Also knows about invertions.

    Examples:
    >>> determine_triad(['A', 'C', 'E'])
    ['A minor triad', 'C major sixth, second inversion']
    >>> determine_triad(['C', 'E', 'A'])
    ['C major sixth', 'A minor triad, first inversion']
    >>> determine_triad(['A', 'C', 'E'], True)
    ['Am', 'CM6']
    """
    if len(triad) != 3:
        # warning: raise exception: not a triad
        return False

    def inversion_exhauster(triad, shorthand, tries, result):
        """Run tries every inversion and save the result."""
        intval1 = intervals.determine(triad[0], triad[1], True)
        intval2 = intervals.determine(triad[0], triad[2], True)

        def add_result(short):
            result.append((short, tries, triad[0]))

        intval = intval1 + intval2
        if intval == "25":
            add_result("sus2")
        elif intval == "3b7":
            add_result("dom7")  # changed from just '7'
        elif intval == "3b5":
            add_result("7b5")  # why not b5?
        elif intval == "35":
            add_result("M")
        elif intval == "3#5":
            add_result("aug")
        elif intval == "36":
            add_result("M6")
        elif intval == "37":
            add_result("M7")
        elif intval == "b3b5":
            add_result("dim")
        elif intval == "b35":
            add_result("m")
        elif intval == "b36":
            add_result("m6")
        elif intval == "b3b7":
            add_result("m7")
        elif intval == "b37":
            add_result("m/M7")
        elif intval == "45":
            add_result("sus4")
        elif intval == "5b7":
            add_result("m7")
        elif intval == "57":
            add_result("M7")
        if tries != 3 and not no_inversions:
            return inversion_exhauster(
                [triad[-1]] + triad[:-1], shorthand, tries + 1, result
            )
        else:
            res = []
            for r in result:
                if shorthand:
                    res.append(r[2] + r[0])
                else:
                    res.append(r[2] + chord_shorthand_meaning[r[0]] + int_desc(r[1]))
            return res

    return inversion_exhauster(triad, shorthand, 1, [])

def int_desc(tries):
    """Return the inversion of the triad in a string."""
    if tries == 1:
        return ""
    elif tries == 2:
        return ", first inversion"
    elif tries == 3:
        return ", second inversion"
    elif tries == 4:
        return ", third inversion"

def determine_polychords(chord, shorthand=False):
    """Determine the polychords in chord.

    This function can handle anything from polychords based on two triads to
    6 note extended chords.
    """
    polychords = []
    function_list = [
        determine_triad,
        determine_seventh,
        determine_extended_chord5,
        determine_extended_chord6,
        determine_extended_chord7,
    ]

    # Range tracking.
    if len(chord) <= 3:
        return []
    elif len(chord) > 14:
        return []
    elif len(chord) - 3 <= 5:
        function_nr = list(range(0, len(chord) - 3))
    else:
        function_nr = list(range(0, 5))
    for f in function_nr:
        for f2 in function_nr:
            # The clever part: Try the function_list[f] on the len(chord) - (3 +
            # f) last notes of the chord. Then try the function_list[f2] on the
            # f2 + 3 first notes of the chord. Thus, trying all possible
            # combinations.
            for chord1 in function_list[f](
                chord[len(chord) - (3 + f) :], True, True, True
            ):
                for chord2 in function_list[f2](chord[: f2 + 3], True, True, True):
                    polychords.append("%s|%s" % (chord1, chord2))
    if shorthand:
        for p in polychords:
            p = p + " polychord"
    return polychords

