def __len__(self):
    """Return the number of notes in the container."""
    return len(self.notes)

def from_chord(self, shorthand):
    """Shortcut to from_chord_shorthand."""
    return self.from_chord_shorthand(shorthand)

def add_notes(self, note, duration=None):
    """Add a Note, note as string or NoteContainer to the last Bar.

    If the Bar is full, a new one will automatically be created.

    If the Bar is not full but the note can't fit in, this method will
    return False. True otherwise.

    An InstrumentRangeError exception will be raised if an Instrument is
    attached to the Track, but the note turns out not to be within the
    range of the Instrument.
    """
    if self.instrument != None:
        if not self.instrument.can_play_notes(note):
            raise InstrumentRangeError(
                "Note '%s' is not in range of the instrument (%s)"
                % (note, self.instrument)
            )
    if duration == None:
        duration = 4

    # Check whether the last bar is full, if so create a new bar and add the
    # note there
    if len(self.bars) == 0:
        self.bars.append(Bar())
    last_bar = self.bars[-1]
    if last_bar.is_full():
        self.bars.append(Bar(last_bar.key, last_bar.meter))
        # warning should hold note if it doesn't fit

    return self.bars[-1].place_notes(note, duration)

def from_chords(self, chords, duration=1):
    """Add chords to the Track.

    The given chords should be a list of shorthand strings or list of
    list of shorthand strings, etc.

    Each sublist divides the value by 2.

    If a tuning is set, chords will be expanded so they have a proper
    fingering.

    Example:
    >>> t = Track().from_chords(['C', ['Am', 'Dm'], 'G7', 'C#'], 1)
    """
    tun = self.get_tuning()

    def add_chord(chord, duration):
        if isinstance(chord, list):
            for c in chord:
                add_chord(c, duration * 2)
        else:
            chord = NoteContainer().from_chord(chord)
            if tun:
                chord = tun.find_chord_fingering(
                    chord, return_best_as_NoteContainer=True
                )
            if not self.add_notes(chord, duration):
                # This should be the standard behaviour of add_notes
                dur = self.bars[-1].value_left()
                self.add_notes(chord, dur)

                # warning should hold note
                self.add_notes(chord, value.subtract(duration, dur))

    for c in chords:
        if c is not None:
            add_chord(c, duration)
        else:
            self.add_notes(None, duration)
    return self

def add_chord(chord, duration):
    if isinstance(chord, list):
        for c in chord:
            add_chord(c, duration * 2)
    else:
        chord = NoteContainer().from_chord(chord)
        if tun:
            chord = tun.find_chord_fingering(
                chord, return_best_as_NoteContainer=True
            )
        if not self.add_notes(chord, duration):
            # This should be the standard behaviour of add_notes
            dur = self.bars[-1].value_left()
            self.add_notes(chord, dur)

            # warning should hold note
            self.add_notes(chord, value.subtract(duration, dur))

def determine(value):
    """Analyse the value and return a tuple containing the parts it's made of.

    The tuple respectively consists of the base note value, the number of
    dots, and the ratio (see tuplet).

    Examples:
    >>> determine(8)
    (8, 0, 1, 1)
    >>> determine(12)
    (8, 0, 3, 2)
    >>> determine(14)
    (8, 0, 7, 4)

    This function recognizes all the base values, triplets, quintuplets,
    septuplets and up to four dots. The values are matched on range.
    """
    i = -2
    for v in base_values:
        if value == v:
            return (value, 0, 1, 1)
        if value < v:
            break
        i += 1
    scaled = float(value) / 2 ** i
    if scaled >= 0.9375:  # base value
        return (base_values[i], 0, 1, 1)
    elif scaled >= 0.8125:
        # septuplet: scaled = 0.875
        return (base_values[i + 1], 0, 7, 4)
    elif scaled >= 17 / 24.0:
        # triplet: scaled = 0.75
        return (base_values[i + 1], 0, 3, 2)
    elif scaled >= 31 / 48.0:
        # dotted note (one dot): scaled = 2/3.0
        return (v, 1, 1, 1)
    elif scaled >= 67 / 112.0:
        # quintuplet: scaled = 0.625
        return (base_values[i + 1], 0, 5, 4)
    d = 3
    for x in range(2, 5):
        d += 2 ** x
        if scaled == 2.0 ** x / d:
            return (v, x, 1, 1)
    return (base_values[i + 1], 0, 1, 1)

def from_Note(note, process_octaves=True, standalone=True):
    """Get a Note object and return the LilyPond equivalent in a string.

    If process_octaves is set to False, all data regarding octaves will be
    ignored. If standalone is True, the result can be used by functions
    like to_png and will produce a valid output. The argument is mostly here
    to let from_NoteContainer make use of this function.
    """
    # Throw exception
    if not hasattr(note, "name"):
        return False

    # Lower the case of the name
    result = note.name[0].lower()

    # Convert #'s and b's to 'is' and 'es' suffixes
    for accidental in note.name[1:]:
        if accidental == "#":
            result += "is"
        elif accidental == "b":
            result += "es"

    # Place ' and , for octaves
    if process_octaves:
        oct = note.octave
        if oct >= 4:
            while oct > 3:
                result += "'"
                oct -= 1
        elif oct < 3:
            while oct < 3:
                result += ","
                oct += 1
    if standalone:
        return "{ %s }" % result
    else:
        return result

def from_NoteContainer(nc, duration=None, standalone=True):
    """Get a NoteContainer object and return the LilyPond equivalent in a
    string.

    The second argument determining the duration of the NoteContainer is
    optional. When the standalone argument is True the result of this
    function can be used directly by functions like to_png. It is mostly
    here to be used by from_Bar.
    """
    # Throw exception
    if nc is not None and not hasattr(nc, "notes"):
        return False

    # Return rests for None or empty lists
    if nc is None or len(nc.notes) == 0:
        result = "r"
    elif len(nc.notes) == 1:

        # Return a single note if the list contains only one note
        result = from_Note(nc.notes[0], standalone=False)
    else:
        # Return the notes grouped in '<' and '>'
        result = "<"
        for notes in nc.notes:
            result += from_Note(notes, standalone=False) + " "
        result = result[:-1] + ">"

    # Add the duration
    if duration != None:
        parsed_value = value.determine(duration)

        # Special case: check for longa and breve in the duration (issue #37)
        dur = parsed_value[0]
        if dur == value.longa:
            result += "\\longa"
        elif dur == value.breve:
            result += "\\breve"
        else:
            result += str(int(parsed_value[0]))
        for i in range(parsed_value[1]):
            result += "."
    if not standalone:
        return result
    else:
        return "{ %s }" % result

def from_Bar(bar, showkey=True, showtime=True):
    """Get a Bar object and return the LilyPond equivalent in a string.

    The showkey and showtime parameters can be set to determine whether the
    key and the time should be shown.
    """
    # Throw exception
    if not hasattr(bar, "bar"):
        return False

    # Process the key
    if showkey:
        key_note = Note(bar.key.key[0].upper() + bar.key.key[1:])
        key = "\\key %s \\%s " % (
            from_Note(key_note, False, standalone=False),
            bar.key.mode,
        )
        result = key
    else:
        result = ""

    # Handle the NoteContainers
    latest_ratio = (1, 1)
    ratio_has_changed = False
    for bar_entry in bar.bar:
        parsed_value = value.determine(bar_entry[1])
        ratio = parsed_value[2:]
        if ratio == latest_ratio:
            result += (
                from_NoteContainer(bar_entry[2], bar_entry[1], standalone=False) + " "
            )
        else:
            if ratio_has_changed:
                result += "}"
            result += "\\times %d/%d {" % (ratio[1], ratio[0])
            result += (
                from_NoteContainer(bar_entry[2], bar_entry[1], standalone=False) + " "
            )
            latest_ratio = ratio
            ratio_has_changed = True
    if ratio_has_changed:
        result += "}"

    # Process the time
    if showtime:
        return "{ \\time %d/%d %s}" % (bar.meter[0], bar.meter[1], result)
    else:
        return "{ %s}" % result

def from_Track(track):
    """Process a Track object and return the LilyPond equivalent in a string."""
    # Throw exception
    if not hasattr(track, "bars"):
        return False
    lastkey = Key("C")
    lasttime = (4, 4)

    # Handle the Bars:
    result = ""
    for bar in track.bars:
        if lastkey != bar.key:
            showkey = True
        else:
            showkey = False
        if lasttime != bar.meter:
            showtime = True
        else:
            showtime = False
        result += from_Bar(bar, showkey, showtime) + " "
        lastkey = bar.key
        lasttime = bar.meter
    return "{ %s}" % result

def from_Composition(composition):
    """Return the LilyPond equivalent of a Composition in a string."""
    # warning Throw exception
    if not hasattr(composition, "tracks"):
        return False
    result = '\\header { title = "%s" composer = "%s" opus = "%s" } ' % (
        composition.title,
        composition.author,
        composition.subtitle,
    )
    for track in composition.tracks:
        result += from_Track(track) + " "
    return result[:-1]

def determine(notes):
    """Determine the scales containing the notes.

    All major and minor scales are recognized.

    Example:
    >>> determine(['A', 'Bb', 'E', 'F#', 'G'])
    ['G melodic minor', 'G Bachian', 'D harmonic major']
    """
    notes = set(notes)
    res = []

    for key in keys:
        for scale in _Scale.__subclasses__():
            if scale.type == "major":
                if notes <= set(scale(key[0]).ascending()) or notes <= set(
                    scale(key[0]).descending()
                ):
                    res.append(scale(key[0]).name)
            elif scale.type == "minor":
                if notes <= set(
                    scale(get_notes(key[1])[0]).ascending()
                ) or notes <= set(scale(get_notes(key[1])[0]).descending()):
                    res.append(scale(get_notes(key[1])[0]).name)
    return res

