    return "Ascending:  {0}\nDescending: {1}".format(
        " ".join(self.ascending()), " ".join(self.descending())
    )

def __eq__(self, other):
    if self.ascending() == other.ascending():
        if self.descending() == other.descending():
            return True
    return False

def ascending(self):
    """Return the list of ascending notes."""
    raise NotImplementedError

def descending(self):
    """Return the list of descending notes."""
    return list(reversed(self.ascending()))

def degree(self, degree_number, direction="a"):
    """Return the asked scale degree.

    The direction of the scale is 'a' for ascending (default) and 'd'
    for descending.
    """
    if degree_number < 1:
        raise RangeError("degree '%s' out of range" % degree_number)
    if direction == "a":
        notes = self.ascending()[:-1]
        return notes[degree_number - 1]
    elif direction == "d":
        notes = list(reversed(self.descending())[:-1])
        return notes[degree_number - 1]
    else:
        raise FormatError("Unrecognised direction '%s'" % direction)

def ascending(self):
    notes = [self.tonic]
    for note in range(5):
        notes.append(intervals.major_second(notes[-1]))
    return notes * self.octaves + [notes[0]]

def get_interval(note, interval, key="C"):
    """Return the note an interval (in half notes) away from the given note.

    This will produce mostly theoretical sound results, but you should use
    the minor and major functions to work around the corner cases.
    """
    intervals = [(notes.note_to_int(key) + x) % 12 for x in [0, 2, 4, 5, 7, 9, 11,]]
    key_notes = keys.get_notes(key)
    for x in key_notes:
        if x[0] == note[0]:
            result = (intervals[key_notes.index(x)] + interval) % 12
    if result in intervals:
        return key_notes[intervals.index(result)] + note[1:]
    else:
        return notes.diminish(key_notes[intervals.index((result + 1) % 12)] + note[1:])

def get_notes(self):
    """Return an iterator that iterates through every bar in the this
    track."""
    for bar in self.bars:
        for beat, duration, notes in bar:
            yield beat, duration, notes

def minor_second(note):
    sec = second(note[0], "C")
    return augment_or_diminish_until_the_interval_is_right(note, sec, 1)

def major_second(note):
    sec = second(note[0], "C")
