def augment_or_diminish_until_the_interval_is_right(note1, note2, interval):
    """A helper function for the minor and major functions.

    You should probably not use this directly.
    """
    cur = measure(note1, note2)
    while cur != interval:
        if cur > interval:
            note2 = notes.diminish(note2)
        elif cur < interval:
            note2 = notes.augment(note2)
        cur = measure(note1, note2)

    # We are practically done right now, but we need to be able to create the
    # minor seventh of Cb and get Bbb instead of B######### as the result
    val = 0
    for token in note2[1:]:
        if token == "#":
            val += 1
        elif token == "b":
            val -= 1

    # These are some checks to see if we have generated too much #'s or too much
    # b's. In these cases we need to convert #'s to b's and vice versa.
    if val > 6:
        val = val % 12
        val = -12 + val
    elif val < -6:
        val = val % -12
        val = 12 + val

    # Rebuild the note
    result = note2[0]
    while val > 0:
        result = notes.augment(result)
        val -= 1
    while val < 0:
        result = notes.diminish(result)
        val += 1
    return result

def from_shorthand(note, interval, up=True):
    """Return the note on interval up or down.

    Examples:
    >>> from_shorthand('A', 'b3')
    'C'
    >>> from_shorthand('D', '2')
    'E'
    >>> from_shorthand('E', '2', False)
    'D'
    """
    # warning should be a valid note.
    if not notes.is_valid_note(note):
        return False

    # [shorthand, interval function up, interval function down]
    shorthand_lookup = [
        ["1", major_unison, major_unison],
        ["2", major_second, minor_seventh],
        ["3", major_third, minor_sixth],
        ["4", major_fourth, major_fifth],
        ["5", major_fifth, major_fourth],
        ["6", major_sixth, minor_third],
        ["7", major_seventh, minor_second],
    ]

    # Looking up last character in interval in shorthand_lookup and calling that
    # function.
    val = False
    for shorthand in shorthand_lookup:
        if shorthand[0] == interval[-1]:
            if up:
                val = shorthand[1](note)
            else:
                val = shorthand[2](note)

    # warning Last character in interval should be 1-7
    if val == False:
        return False

    # Collect accidentals
    for x in interval:
        if x == "#":
            if up:
                val = notes.augment(val)
            else:
                val = notes.diminish(val)
        elif x == "b":
            if up:
                val = notes.diminish(val)
            else:
                val = notes.augment(val)
        else:
            return val

def change_note_duration(self, at, to):
    """Change the note duration at the given index to the given
    duration."""
    if _meter.valid_beat_duration(to):
        diff = 0
        for x in self.bar:
            if diff != 0:
                x[0][0] -= diff
            if x[0] == at:
                cur = x[0][1]
                x[0][1] = to
                diff = 1 / cur - 1 / to

def _consonance_test(self, testfunc, param=None):
    """Private function used for testing consonance/dissonance."""
    n = list(self.notes)
    while len(n) > 1:
        first = n[0]
        for second in n[1:]:
            if param is None:
                if not testfunc(first.name, second.name):
                    return False
            else:
                if not testfunc(first.name, second.name, param):
                    return False
        n = n[1:]
    return True

def is_consonant(self, include_fourths=True):
    """Test whether the notes are consonants.

    See the core.intervals module for a longer description on
    consonance.
    """
    return self._consonance_test(intervals.is_consonant, include_fourths)

def is_perfect_consonant(self, include_fourths=True):
    """Test whether the notes are perfect consonants.

    See the core.intervals module for a longer description on
    consonance.
    """
    return self._consonance_test(intervals.is_perfect_consonant, include_fourths)

def is_imperfect_consonant(self):
    """Test whether the notes are imperfect consonants.

    See the core.intervals module for a longer description on
    consonance.
    """
    return self._consonance_test(intervals.is_imperfect_consonant)

def is_dissonant(self, include_fourths=False):
    """Test whether the notes are dissonants.

    See the core.intervals module for a longer description.
    """
    return not self.is_consonant(not include_fourths)

def __eq__(self, other):
    """Compare Notes for equality by comparing their note values."""
    if other is None:
        return False
    return int(self) == int(other)

def get_val(note):
    """Private function: count the value of accidentals."""
    r = 0
    for x in note[1:]:
        if x == "b":
            r -= 1
        elif x == "#":
            r += 1
    return r

def _gcd(a=None, b=None, terms=None):
    """Return greatest common divisor using Euclid's Algorithm."""
    if terms:
        return reduce(lambda a, b: _gcd(a, b), terms)
    else:
        while b:
            (a, b) = (b, a % b)
        return a

def _lcm(a=None, b=None, terms=None):
    """Return lowest common multiple."""
    if terms:
        return reduce(lambda a, b: _lcm(a, b), terms)
    else:
        return (a * b) / _gcd(a, b)

def _track2musicxml(track):
    doc = Document()
    clef = None
    track_node = doc.createElement("part")
    track_node.setAttribute("id", str(id(track)))
    if track.instrument:  # try to guess the clef of the instrument
        if "treble" in track.instrument.clef.lower():
            clef = ("G", "2")
        elif "bass" in track.instrument.clef.lower():
            clef = ("F", "4")
        elif "french" in track.instrument.clef.lower():
            clef = ("G", "1")
        elif "baritone" in track.instrument.clef.lower():
            clef = ("F", "3")
        elif "subbass" in track.instrument.clef.lower():
            clef = ("F", "5")
        elif "alto" in track.instrument.clef.lower():
            clef = ("C", "3")
        elif "tenor" in track.instrument.clef.lower():
            clef = ("C", "4")
        elif "mezzo-soprano" in track.instrument.clef.lower():
            clef = ("C", "2")
        elif "soprano" in track.instrument.clef.lower():
            clef = ("C", "1")
    counter = 1
    for b in track.bars:
        bar = _bar2musicxml(b)
        bar.setAttribute("number", str(counter))
        if clef:
            attrs = bar.getElementsByTagName("attributes")
            for attr in attrs:
                clef_node = doc.createElement("clef")
                sign = doc.createElement("sign")
                line = doc.createElement("line")
                sign.appendChild(doc.createTextNode(clef[0]))
                line.appendChild(doc.createTextNode(clef[1]))
                clef_node.appendChild(sign)
                clef_node.appendChild(line)
                attr.appendChild(clef_node)
        track_node.appendChild(bar)
        counter += 1
    return track_node

def from_Note(note):
    c = Composition()
    c.add_note(note)
    return _composition2musicxml(c).toprettyxml()

def from_Bar(bar):
    c = Composition()
    t = Track()
    t.add_bar(bar)
    c.add_track(t)
    return _composition2musicxml(c).toprettyxml()

def from_Track(track):
    c = Composition()
    c.add_track(track)
    return _composition2musicxml(c).toprettyxml()

def __getitem__(self, index):
    """Enable the '[]' notation."""
    return self.compositions[index]

def find_fingering(self, notes, max_distance=4, not_strings=None):
    """Return a list [(string, fret)] of possible fingerings for
    'notes'.

    The notes parameter should be a list of strings or Notes or a
    NoteContainer; max_distance denotes the maximum distance between
    frets; not_strings can be used to disclude certain strings and is
    used internally to recurse.

    Example:
    >>> t = StringTuning('test', 'test', ['A-3', 'E-4', 'A-5'])
    >>> t.find_fingering(['E-4', 'B-4'])
    [[(0, 7), (1, 7)], [(1, 0), (0, 14)]]
    """
    if not_strings is None:
        not_strings = []
    if notes is None:
        return []
    if len(notes) == 0:
        return []
    first = notes[0]
    notes = notes[1:]
    frets = self.find_frets(first)
    result = []
    for (string, fret) in enumerate(frets):
        if fret is not None and string not in not_strings:
            if len(notes) > 0:
                # recursively find fingerings for
                # remaining notes
                r = self.find_fingering(notes, max_distance, not_strings + [string])
                if r != []:
                    for f in r:
                        result.append([(string, fret)] + f)
            else:
                result.append([(string, fret)])

    # filter impossible fingerings and sort
    res = []
    for r in result:
        (min, max) = (1000, -1)
        frets = 0
        for (string, fret) in r:
            if fret > max:
                max = fret
            if fret < min and fret != 0:
                min = fret
            frets += fret
        if 0 <= max - min < max_distance or min == 1000 or max == -1:
            res.append((frets, r))
    return [r for (_, r) in sorted(res)]

def frets_to_NoteContainer(self, fingering):
    """Convert a list such as returned by find_fret to a NoteContainer."""

    res = []
    for (string, fret) in enumerate(fingering):
        if fret is not None:
            res.append(self.get_Note(string, fret))
    return NoteContainer(res)

def from_Note(note, width=80, tuning=None):
    """Return a string made out of ASCII tablature representing a Note object
    or note string.

    Throw a RangeError if a suitable fret can't be found.

    'tuning' should be a StringTuning object or None for the default tuning.

    To force a certain fingering you can use a 'string' and 'fret' attribute
    on the Note. If the fingering is valid, it will get used instead of the
    default one.
    """
    if tuning is None:
        tuning = default_tuning
    result = begin_track(tuning)
    min = 1000
    (s, f) = (-1, -1)

    # Do an attribute check
    if hasattr(note, "string") and hasattr(note, "fret"):
        n = tuning.get_Note(note.string, note.fret)
        if n is not None and int(n) == int(note):
            (s, f) = (note.string, note.fret)
            min = 0

    if min == 1000:
        for (string, fret) in enumerate(tuning.find_frets(note)):
            if fret is not None:
                if fret < min:
                    min = fret
                    (s, f) = (string, fret)
    l = len(result[0])
    w = max(4, (width - l) - 1)

    # Build ASCII
    if min != 1000:
        fret = str(f)
        for i in range(len(result)):
            d = len(fret)
            if i != s:
                result[i] += "-" * w + "|"
            else:
                d = w - len(fret)
                result[i] += "-" * (d // 2) + fret
                d = (w - d // 2) - len(fret)
                result[i] += "-" * d + "|"
    else:
        raise RangeError(
            "No fret found that could play note '%s'. " "Note out of range." % note
        )
    result.reverse()
    return os.linesep.join(result)

def from_NoteContainer(notes, width=80, tuning=None):
    """Return a string made out of ASCII tablature representing a
    NoteContainer object or list of note strings / Note objects.

    Throw a FingerError if no playable fingering can be found.

    'tuning' should be a StringTuning object or None for the default tuning.

    To force a certain fingering you can use a 'string' and 'fret' attribute
    on one or more of the Notes. If the fingering is valid, it will get used
    instead of the default one.
    """
    if tuning is None:
        tuning = default_tuning
    result = begin_track(tuning)
    l = len(result[0])
    w = max(4, (width - l) - 1)
    fingerings = tuning.find_fingering(notes)
    if fingerings != []:
        # Do an attribute check
        f = []
        attr = []
        for note in notes:
            if hasattr(note, "string") and hasattr(note, "fret"):
                n = tuning.get_Note(note.string, note.fret)
                if n is not None and int(n) == int(note):
                    f += (note.string, note.fret)
                    attr.append(int(note))

        # See if there are any possible fingerings with the attributes
        # that are set.
        fres = []
        if f != []:
            for x in fingerings:
                found = True
                for pos in f:
                    if pos not in x:
                        found = False
                if found:
                    fres.append(x)

        # Use best fingering.
        if fres != []:
            f = fres[0]
        else:
            # Use default fingering if attributes don't make sense
            f = fingerings[0]

        # Build {string: fret} result
        res = {}
        for (string, fret) in f:
            res[string] = str(fret)
        maxfret = max(res.values())

        # Produce ASCII
        for i in range(len(result)):
            if i not in res:
                result[i] += "-" * w + "|"
            else:
                d = w - len(res[i])
                result[i] += "-" * (d // 2) + res[i]
                d = (w - d // 2) - len(res[i])
                result[i] += "-" * d + "|"
    else:
        raise FingerError("No playable fingering found for: %s" % notes)
    result.reverse()
    return os.linesep.join(result)

def from_Bar(bar, width=40, tuning=None, collapse=True):
    """Convert a mingus.containers.Bar object to ASCII tablature.

    Throw a FingerError if no playable fingering can be found.

    'tuning' should be a StringTuning object or None for the default tuning.
    If 'collapse' is False this will return a list of lines, if it's True
    all lines will be concatenated with a newline symbol.

    Use 'string' and 'fret' attributes on Notes to force certain fingerings.
    """
    if tuning is None:
        tuning = default_tuning

    # Size of a quarter note
    qsize = _get_qsize(tuning, width)
    result = begin_track(tuning, max(2, qsize // 2))

    # Add bar
    for entry in bar.bar:
        (beat, duration, notes) = entry
        fingering = tuning.find_fingering(notes)
        if fingering != [] or notes is None:

            # Do an attribute check
            f = []
            attr = []
            if notes is not None:
                for note in notes:
                    if hasattr(note, "string") and hasattr(note, "fret"):
                        n = tuning.get_Note(note.string, note.fret)
                        if n is not None and int(n) == int(note):
                            f.append((note.string, note.fret))
                            attr.append(int(note))

            # See if there are any possible fingerings with the attributes that
            # are set.
            fres = []
            if f != []:
                for x in fingering:
                    found = True
                    for pos in f:
                        if pos not in x:
                            found = False
                    if found:
                        fres.append(x)

            # Use best fingering.
            maxlen = 0
            if fres != []:
                f = fres[0]
            else:
                # Use default fingering if attributes don't make sense
                if notes is None:
                    f = []
                    maxlen = 1
                else:
                    f = fingering[0]

            # Make {string: fret} dictionary and find highest fret
            d = {}
            for (string, fret) in f:
                d[string] = str(fret)
                if len(str(fret)) > maxlen:
                    maxlen = len(str(fret))

            # Add to result
            for i in range(len(result)):
                dur = int(((1.0 / duration) * qsize) * 4) - maxlen
                if i not in d:
                    result[i] += "-" * maxlen + "-" * dur
                else:
                    result[i] += ("%" + str(maxlen) + "s") % d[i] + "-" * dur
        else:
            raise FingerError("No playable fingering found for: %s" % notes)

    # Padding at the end
    l = len(result[i]) + 1
    for i in range(len(result)):
        result[i] += (width - l) * "-" + "|"
    result.reverse()

    # Mark quarter notes
    pad = " " * int(((1.0 / bar.meter[1]) * qsize) * 4 - 1)
    r = (
        " " * (result[0].find("||") + 2 + max(2, qsize // 2))
        + ("*" + pad) * bar.meter[0]
    )
    r += " " * (len(result[0]) - len(r))
    if not collapse:
        return [r] + result
    else:
        return os.linesep.join([r] + result)

