def from_Track(track, maxwidth=80, tuning=None):
    """Convert a mingus.containers.Track object to an ASCII tablature string.

    'tuning' should be set to a StringTuning object or to None to use the
    Track's tuning (or alternatively the default if the Track hasn't got its
    own tuning).

    'string' and 'fret' attributes on Notes are taken into account.
    """
    result = []
    width = _get_width(maxwidth)
    if not tuning:
        tuning = track.get_tuning()
    lastlen = 0
    for bar in track:
        r = from_Bar(bar, width, tuning, collapse=False)
        barstart = r[1].find("||") + 2
        if (len(r[0]) + lastlen) - barstart < maxwidth and result != []:
            for i in range(1, len(r) + 1):
                item = r[len(r) - i]
                result[-i] += item[barstart:]
        else:
            result += ["", ""] + r
        lastlen = len(result[-1])
    return os.linesep.join(result)

def _get_width(maxwidth):
    """Return the width of a single bar, when width of the page is given."""
    width = maxwidth / 3
    if maxwidth <= 60:
        width = maxwidth
    elif 60 < maxwidth <= 120:
        width = maxwidth / 2
    return width

def find_notes(freqTable, maxNote=100):
    """Convert the (frequencies, amplitude) list to a (Note, amplitude) list."""
    res = [0] * 129
    n = Note()
    for (freq, ampl) in freqTable:
        if freq > 0 and ampl > 0:
            f = _find_log_index(freq)
            if f < maxNote:
                res[f] += ampl
            else:
                res[128] += ampl
    return [(Note().from_int(x) if x < 128 else None, n) for (x, n) in enumerate(res)]

def find_melody(file="440_480_clean.wav", chunksize=512):
    """Cut the sample into chunks and analyze each chunk.

    Return a list [(Note, chunks)] where chunks is the number of chunks
    where that note is the most dominant.

    If two consequent chunks turn out to return the same Note they are
    grouped together.

    This is an experimental function.
    """
    (data, freq, bits) = data_from_file(file)
    res = []
    for d in analyze_chunks(data, freq, bits, chunksize):
        if res != []:
            if res[-1][0] == d:
                val = res[-1][1]
                res[-1] = (d, val + 1)
            else:
                res.append((d, 1))
        else:
            res.append((d, 1))
    return [(x, freq) for (x, freq) in res]

def __init__(self, notes=None):
    if notes is None:
        notes = []
    self.empty()
    self.add_notes(notes)

def empty(self):
    """Empty the container."""
    self.notes = []

def add_note(self, note, octave=None, dynamics=None):
    """Add a note to the container and sorts the notes from low to high.

    The note can either be a string, in which case you could also use
    the octave and dynamics arguments, or a Note object.
    """
    if dynamics is None:
        dynamics = {}
    if isinstance(note, six.string_types):
        if octave is not None:
            note = Note(note, octave, dynamics)
        elif len(self.notes) == 0:
            note = Note(note, 4, dynamics)
        else:
            if Note(note, self.notes[-1].octave) < self.notes[-1]:
                note = Note(note, self.notes[-1].octave + 1, dynamics)
            else:
                note = Note(note, self.notes[-1].octave, dynamics)
    if not hasattr(note, "name"):
        raise UnexpectedObjectError(
            "Object '%s' was not expected. "
            "Expecting a mingus.containers.Note object." % note
        )
    if note not in self.notes:
        self.notes.append(note)
        self.notes.sort()
    return self.notes

def add_notes(self, notes):
    """Feed notes to self.add_note.

    The notes can either be an other NoteContainer, a list of Note
    objects or strings or a list of lists formatted like this:
    >>> notes = [['C', 5], ['E', 5], ['G', 6]]

    or even:
    >>> notes = [['C', 5, {'velocity': 20}], ['E', 6, {'velocity': 20}]]
    """
    if hasattr(notes, "notes"):
        for x in notes.notes:
            self.add_note(x)
        return self.notes
    elif hasattr(notes, "name"):
        self.add_note(notes)
        return self.notes
    elif isinstance(notes, six.string_types):
        self.add_note(notes)
        return self.notes
    for x in notes:
        if isinstance(x, list) and len(x) != 1:
            if len(x) == 2:
                self.add_note(x[0], x[1])
            else:
                self.add_note(x[0], x[1], x[2])
        else:
            self.add_note(x)
    return self.notes

def from_progression(self, shorthand, key="C"):
    """Shortcut to from_progression_shorthand."""
    return self.from_progression_shorthand(shorthand, key)

def sort(self):
    """Sort the notes in the container from low to high."""
    self.notes.sort()

def from_interval(self, startnote, shorthand, up=True):
    """Shortcut to from_interval_shorthand."""
    return self.from_interval_shorthand(startnote, shorthand, up)

def remove_note(self, note, octave=-1):
    """Remove note from container.

    The note can either be a Note object or a string representing the
    note's name. If no specific octave is given, the note gets removed
    in every octave.
    """
    res = []
    for x in self.notes:
        if isinstance(note, six.string_types):
            if x.name != note:
                res.append(x)
            else:
                if x.octave != octave and octave != -1:
                    res.append(x)
        else:
            if x != note:
                res.append(x)
    self.notes = res
    return res

def remove_notes(self, notes):
    """Remove notes from the containers.

    This function accepts a list of Note objects or notes as strings and
    also single strings or Note objects.
    """
    if isinstance(notes, six.string_types):
        return self.remove_note(notes)
    elif hasattr(notes, "name"):
        return self.remove_note(notes)
    else:
        for x in notes:
            self.remove_note(x)
        return self.notes

def remove_duplicate_notes(self):
    """Remove duplicate and enharmonic notes from the container."""
    res = []
    for x in self.notes:
        if x not in res:
            res.append(x)
    self.notes = res
    return res

def diminish(self):
    """Diminish all the notes in the NoteContainer."""
    for n in self.notes:
        n.diminish()

def diminish(self):
    """Diminish the NoteContainers in Bar."""
    for cont in self.bar:
        cont[2].diminish()

def remove_redundant_accidentals(self):
    """Call notes.remove_redundant_accidentals on this note's name."""
    self.name = notes.remove_redundant_accidentals(self.name)

def system_reset(self):
    """Stop all notes and reset all programs."""
    return fluid_synth_system_reset(self.synth)

def augment(self):
    """Augment all the notes in the NoteContainer."""
    for n in self.notes:
        n.augment()

def __eq__(self, other):
    """Enable the '==' operator for NoteContainer instances."""
    for x in self:
        if x not in other:
            return False
    return True

def place_notes_at(self, notes, at):
    """Place notes at the given index."""
    for x in self.bar:
        if x[0] == at:
            x[0][2] += notes

def augment(self):
    """Augment the NoteContainers in Bar."""
    for cont in self.bar:
        cont[2].augment()

def augment(self):
    """Call notes.augment with this note as argument."""
    self.name = notes.augment(self.name)

def transpose(self, interval, up=True):
    """Transpose all the notes in the container up or down the given
    interval."""
    for n in self.notes:
        n.transpose(interval, up)
    return self

def transpose(self, interval, up=True):
    """Transpose the notes in the bar up or down the interval.

    Call transpose() on all NoteContainers in the bar.
    """
    for cont in self.bar:
        cont[2].transpose(interval, up)

def change_octave(self, diff):
    """Change the octave of the note to the current octave + diff."""
    self.octave += diff
    if self.octave < 0:
        self.octave = 0

def octave_up(self):
    """Increment the current octave with 1."""
    self.change_octave(1)

def octave_down(self):
    """Decrement the current octave with 1."""
    self.change_octave(-1)

def __repr__(self):
    """Return a nice and clean string representing the note container."""
    return str(self.notes)

def __getitem__(self, index):
    """Enable the  '[]' notation on Bars to get the item at the index."""
    return self.bar[index]

def empty(self):
    """Remove all the tracks from this class."""
    self.tracks = []

def add_note(self, note):
    """Add a note to the selected tracks.

    Everything container.Track supports in __add__ is accepted.
    """
    for n in self.selected_tracks:
        self.tracks[n] + note

def __add__(self, value):
    """Enable the '+' operator for Compositions.

    Notes, note strings, NoteContainers, Bars and Tracks are accepted.
    """
    if hasattr(value, "bars"):
        return self.add_track(value)
    else:
        return self.add_note(value)

def __getitem__(self, index):
    """Enable the '[]' notation."""
    return self.tracks[index]

def __add__(self, value):
    """Enable the '+' operator for Tracks.

    Notes, notes as string, NoteContainers and Bars accepted.
    """
    if hasattr(value, "bar"):
        return self.add_bar(value)
    elif hasattr(value, "notes"):
        return self.add_notes(value)
    elif hasattr(value, "name") or isinstance(value, six.string_types):
        return self.add_notes(value)

def __eq__(self, other):
    """Enable the '==' operator for tracks."""
    for x in range(0, len(self.bars) - 1):
        if self.bars[x] != other.bars[x]:
            return False
    return True

def __getitem__(self, index):
    """Enable the '[]' notation for Tracks."""
    return self.bars[index]

def __len__(self):
    """Enable the len() function for Tracks."""
    return len(self.bars)

def __setitem__(self, index, value):
    """Enable the '[] =' notation."""
    self.tracks[index] = value

def __len__(self):
    """Enable the len() function."""
    return len(self.tracks)

def __len__(self):
    """Enable the len() function."""
    return len(self.compositions)

def place_rest(self, duration):
    """Place a rest of given duration on the current_beat.

    The same as place_notes(None, duration).
    """
    return self.place_notes(None, duration)

def is_full(self):
    """Return False if there is room in this Bar for another
    NoteContainer, True otherwise."""
    if self.length == 0.0:
        return False
    if len(self.bar) == 0:
        return False
    if self.current_beat >= self.length - 0.001:
        return True
    return False

def space_left(self):
    """Return the space left on the Bar."""
    return self.length - self.current_beat

def value_left(self):
    """Return the value left on the Bar."""
    return 1.0 / self.space_left()

def __add__(self, note_container):
    """Enable the '+' operator on Bars."""
    if self.meter[1] != 0:
        return self.place_notes(note_container, self.meter[1])
    else:
        return self.place_notes(note_container, 4)

def __setitem__(self, index, value):
    """Enable the use of [] = notation on Bars.

    The value should be a NoteContainer, or a string/list/Note
    understood by the NoteContainer.
    """
    if hasattr(value, "notes"):
        pass
    elif hasattr(value, "name"):
        value = NoteContainer(value)
    elif isinstance(value, six.string_types):
        value = NoteContainer(value)
    elif isinstance(value, list):
        res = NoteContainer()
        for x in value:
            res + x
        value = res
    self.bar[index][2] = value

def __repr__(self):
    """Enable str() and repr() for Bars."""
    return str(self.bar)

def __len__(self):
    """Enable the len() method for Bars."""
    return len(self.bar)

def __eq__(self, other):
    """Enable the '==' operator for Bars."""
    for b in range(0, len(self.bar) - 1):
        if self.bar[b] != other.bar[b]:
            return False
    return True

def test_integrity(self):
    """Test whether all but the last Bars contained in this track are
    full."""
    for b in self.bars[:-1]:
        if not b.is_full():
            return False
    return True

def get_range(self):
    """Return the highest and the lowest note in a tuple."""
    (min, max) = (100000, -1)
    for cont in self.bar:
        for note in cont[2]:
            if int(note) < int(min):
                min = note
            elif int(note) > int(max):
                max = note
    return (min, max)

def __setitem__(self, index, value):
    """Enable the '[] =' notation."""
    if not hasattr(value, "tracks"):
        raise UnexpectedObjectError(
            "Object '%s' is not expected. "
            "Expecting a "
            "mingus.containers.Composition object." % value
        )
    self.compositions[index] = value

def __add__(self, composition):
    """Enable the '+' operator for Compositions."""
    return self.add_composition(composition)

def set_range(self, range):
    """Set the range of the instrument.

    A range is a tuple of two Notes or note strings.
    """
    if isinstance(range[0], six.string_types):
        range[0] = Note(range[0])
        range[1] = Note(range[1])
    if not hasattr(range[0], "name"):
        raise UnexpectedObjectError(
            "Unexpected object '%s'. "
            "Expecting a mingus.containers.Note object" % range[0]
        )
    self.range = range

def set_instrument(channel, midi_instr, bank=0):
    """Set the midi instrument on channel."""
    return midi.set_instrument(channel, midi_instr, bank)

def note_in_range(self, note):
    """Test whether note is in the range of this Instrument.

    Return True if so, False otherwise.
    """
    if isinstance(note, six.string_types):
        note = Note(note)
    if not hasattr(note, "name"):
        raise UnexpectedObjectError(
            "Unexpected object '%s'. "
            "Expecting a mingus.containers.Note object" % note
        )
    if note >= self.range[0] and note <= self.range[1]:
        return True
    return False

def notes_in_range(self, notes):
    """An alias for can_play_notes."""
    return self.can_play_notes(notes)

def can_play_notes(self, notes):
    """Test if the notes lie within the range of the instrument.

    Return True if so, False otherwise.
    """
    if hasattr(notes, "notes"):
        notes = notes.notes
    if not isinstance(notes, list):
        notes = [notes]
    for n in notes:
        if not self.note_in_range(n):
            return False
    return True

def can_play_notes(self, notes):
    if len(notes) > 6:
        return False
    return Instrument.can_play_notes(self, notes)

def get_midi_data(self):
    """Collect and return the raw, binary MIDI data from the tracks."""
    tracks = [t.get_midi_data() for t in self.tracks if t.track_data != b""]
    return self.header() + b"".join(tracks)

def write_file(self, file, verbose=False):
    """Collect the data from get_midi_data and write to file."""
    dat = self.get_midi_data()
    try:
        f = open(file, "wb")
    except:
        print("Couldn't open '%s' for writing." % file)
        return False
    try:
        f.write(dat)
    except:
        print("An error occured while writing data to %s." % file)
        return False
    f.close()
    if verbose:
        print("Written %d bytes to %s." % (len(dat), file))
    return True

def write_Composition(file, composition, bpm=120, repeat=0, verbose=False):
    """Write a mingus.Composition to a MIDI file."""
    m = MidiFile()
    t = []
    for x in range(len(composition.tracks)):
        t += [MidiTrack(bpm)]
    m.tracks = t
    while repeat >= 0:
        for i in range(len(composition.tracks)):
            m.tracks[i].play_Track(composition.tracks[i])
        repeat -= 1
    return m.write_file(file, verbose)

def play_Track(self, track):
    """Convert a Track object to MIDI events and write them to the
    track_data."""
    if hasattr(track, "name"):
        self.set_track_name(track.name)
    self.delay = 0
    instr = track.instrument
    if hasattr(instr, "instrument_nr"):
        self.change_instrument = True
        self.instrument = instr.instrument_nr
    for bar in track:
        self.play_Bar(bar)

def __init__(self, start_bpm=120):
    self.track_data = b""
    self.set_tempo(start_bpm)

def augment(self):
    """Augment all the bars in the Track."""
    for bar in self.bars:
        bar.augment()
    return self

def diminish(self):
    """Diminish all the bars in the Track."""
    for bar in self.bars:
        bar.diminish()
    return self

def __init__(self, name="C", octave=4, dynamics=None, velocity=None, channel=None):
    """
    :param name:
    :param octave:
    :param dynamics: Deprecated. Use `velocity` and `channel` directly.
    :param int velocity: Integer (0-127)
    :param int channel: Integer (0-15)
    """
    if dynamics is None:
        dynamics = {}

    if velocity is not None:
        dynamics["velocity"] = velocity
    if channel is not None:
        dynamics["channel"] = channel

    if isinstance(name, six.string_types):
        self.set_note(name, octave, dynamics)
    elif hasattr(name, "name"):
        # Hardcopy Note object
        self.set_note(name.name, name.octave, name.dynamics)
    elif isinstance(name, int):
        self.from_int(name)
    else:
        raise NoteFormatError("Don't know what to do with name object: %r" % name)

def dynamics(self):
    """
    .. deprecated:: Provided only for compatibility with existing code.
    """
    return {
        "channel": self.channel,
        "velocity": self.velocity,
    }

def set_channel(self, channel):
    if not 0 <= channel < 16:
        raise ValueError("MIDI channel must be 0-15")
    self.channel = channel

def set_velocity(self, velocity):
    if not 0 <= velocity < 128:
        raise ValueError("MIDI velocity must be 0-127")
    self.velocity = velocity

def set_note(self, name="C", octave=4, dynamics=None, velocity=None, channel=None):
    """Set the note to name in octave with dynamics.

    Return the objects if it succeeded, raise an NoteFormatError
    otherwise.

    :param name:
    :param octave:
    :param dynamics: Deprecated. Use `velocity` and `channel` directly.
    :param int velocity: Integer (0-127)
    :param int channel: Integer (0-15)
    :return:
    """
    if dynamics is None:
        dynamics = {}

    if velocity is not None:
        self.set_velocity(velocity)
    elif "velocity" in dynamics:
        self.set_velocity(dynamics["velocity"])

    if channel is not None:
        self.set_channel(channel)
    if "channel" in dynamics:
        self.set_channel(dynamics["channel"])

    dash_index = name.split("-")
    if len(dash_index) == 1:
        if notes.is_valid_note(name):
            self.name = name
            self.octave = octave
            return self
        else:
            raise NoteFormatError("Invalid note representation: %r" % name)
    elif len(dash_index) == 2:
        note, octave = dash_index
        if notes.is_valid_note(note):
            self.name = note
            self.octave = int(octave)
            return self
        else:
            raise NoteFormatError("Invalid note representation: %r" % name)
    else:
        raise NoteFormatError("Invalid note representation: %r" % name)

def from_shorthand(self, shorthand):
    """Convert from traditional Helmhotz pitch notation.

    Examples:
    >>> Note().from_shorthand("C,,")
    'C-0'
    >>> Note().from_shorthand("C")
    'C-2'
    >>> Note().from_shorthand("c'")
    'C-4'
    """
    name = ""
    octave = 0
    for x in shorthand:
        if x in ["a", "b", "c", "d", "e", "f", "g"]:
            name = str.upper(x)
            octave = 3
        elif x in ["A", "B", "C", "D", "E", "F", "G"]:
            name = x
            octave = 2
        elif x in ["#", "b"]:
            name += x
        elif x == ",":
            octave -= 1
        elif x == "'":
            octave += 1
    return self.set_note(name, octave, {})

def delete(self):
    if self.audio_driver is not None:
        delete_fluid_audio_driver(self.audio_driver)
    delete_fluid_synth(self.synth)
    delete_fluid_settings(self.settings)

def program_change(self, chan, prg):
