def noteoff(self, chan, key):
    """Stop a note."""
    if key < 0 or key > 128:
        return False
    if chan < 0:
        return False
    return fluid_synth_noteoff(self.synth, chan, key)

def stop_Note(note, channel=1):
    """Stop the Note playing at channel.

    If a channel attribute is set on the note, it will take presedence.
    """
    return midi.stop_Note(note, channel)

def stop_NoteContainer(nc, channel=1):
    """Use stop_Note to stop the notes in NoteContainer nc."""
    return midi.stop_NoteContainer(nc, channel)

def stop_everything():
    """Stop all the playing notes on all channels."""
    return midi.stop_everything()

def detach(self, listener):
    """Detach a listening object so that it won't receive any events
    anymore."""
    if listener in self.listeners:
        self.listeners.remove(listener)

def stop_Note(self, note, channel=1):
    """Stop a note on a channel.

    If Note.channel is set, it will take presedence over the channel
    argument given here.
    """
    if hasattr(note, "channel"):
        channel = note.channel
    self.stop_event(int(note) + 12, int(channel))
    self.notify_listeners(
        self.MSG_STOP_INT, {"channel": int(channel), "note": int(note) + 12}
    )
    self.notify_listeners(
        self.MSG_STOP_NOTE, {"channel": int(channel), "note": note}
    )
    return True

def stop_everything(self):
    """Stop all the notes on all channels."""
    for x in range(118):
        for c in range(16):
            self.stop_Note(x, c)

def stop_NoteContainer(self, nc, channel=1):
    """Stop playing the notes in NoteContainer nc."""
    self.notify_listeners(self.MSG_STOP_NC, {"notes": nc, "channel": channel})
    if nc is None:
        return True
    for note in nc:
        if not self.stop_Note(note, channel):
            return False
    return True

def set_meter(self, meter=(4, 4)):
    """Add a time signature event for meter to track_data."""
    self.track_data += self.time_signature_event(meter)

def set_key(self, key="C"):
    """Add a key signature event to the track_data."""
    if isinstance(key, Key):
        key = key.name[0]
    self.track_data += self.key_signature_event(key)

def key_signature_event(self, key="C"):
    """Return the bytes for a key signature event."""
    if key.islower():
        val = minor_keys.index(key) - 7
        mode = b"\x01"
    else:
        val = major_keys.index(key) - 7
        mode = b"\x00"
    if val < 0:
        val = 256 + val
    key = a2b_hex("%02x" % val)
    return self.delta_time + META_EVENT + KEY_SIGNATURE + b"\x02" + key + mode

def set_track_name(self, name):
    """Add a meta event for the track."""
    self.track_data += self.track_name_event(name)

def track_name_event(self, name):
    """Return the bytes for a track name meta event."""
    l = self.int_to_varbyte(len(name))
    return b"\x00" + META_EVENT + TRACK_NAME + l + name.encode("ascii")

def cfunc(name, result, *args):
    """Build and apply a ctypes prototype complete with parameter flags."""
    atypes = []
    aflags = []
    for arg in args:
        atypes.append(arg[1])
        aflags.append((arg[2], arg[0]) + arg[3:])
    return CFUNCTYPE(result, *atypes)((name, _fl), tuple(aflags))

def attach(self, listener):
    """Attach an object that should be notified of events.

    The object should have a notify(msg_type, param_dict) function.
    """
    if listener not in self.listeners:
        self.listeners.append(listener)

def sleep(self, seconds):
    if hasattr(self, "wav"):
        samples = fs.raw_audio_string(self.fs.get_samples(int(seconds * 44100)))
        self.wav.writeframes(bytes(samples))
    else:
        time.sleep(seconds)

