def rawNoteOn(self, pitch, channel=1, v=60):
    midimsg = 0x90 + ((pitch) * 0x100) + (v * 0x10000) + channel
    mm = c_int(midimsg)
    rc = self.winmm.midiOutShortMsg(self.hmidi, mm)
    if rc != 0:
        raise Win32MidiException(
            "Error sending event, "
            + self.midiOutShortErrorCodes.get(rc, "Unknown error.")
        )

def notify(self, msg_type, params):
    if msg_type == Sequencer.MSG_PLAY_INT:
        self.play_int_note_event(
            params["note"], params["channel"], params["velocity"]
        )
    elif msg_type == Sequencer.MSG_STOP_INT:
        self.stop_int_note_event(params["note"], params["channel"])
    elif msg_type == Sequencer.MSG_CC:
        self.cc_event(params["channel"], params["control"], params["value"])
    elif msg_type == Sequencer.MSG_INSTR:
        self.instr_event(params["channel"], params["instr"], params["bank"])
    elif msg_type == Sequencer.MSG_SLEEP:
        self.sleep(params["s"])
    elif msg_type == Sequencer.MSG_PLAY_NOTE:
        self.play_Note(params["note"], params["channel"], params["velocity"])
    elif msg_type == Sequencer.MSG_STOP_NOTE:
        self.stop_Note(params["note"], params["channel"])
    elif msg_type == Sequencer.MSG_PLAY_NC:
        self.play_NoteContainer(params["notes"], params["channel"])
    elif msg_type == Sequencer.MSG_STOP_NC:
        self.stop_NoteContainer(params["notes"], params["channel"])
    elif msg_type == Sequencer.MSG_PLAY_BAR:
        self.play_Bar(params["bar"], params["channel"], params["bpm"])
    elif msg_type == Sequencer.MSG_PLAY_BARS:
        self.play_Bars(params["bars"], params["channels"], params["bpm"])
    elif msg_type == Sequencer.MSG_PLAY_TRACK:
        self.play_Track(params["track"], params["channel"], params["bpm"])
    elif msg_type == Sequencer.MSG_PLAY_TRACKS:
        self.play_Tracks(params["tracks"], params["channels"], params["bpm"])
    elif msg_type == Sequencer.MSG_PLAY_COMPOSITION:
        self.play_Composition(
            params["composition"], params["channels"], params["bpm"]
        )

def play_NoteContainer(nc, channel=1, velocity=100):
    """Use play_Note to play the Notes in the NoteContainer nc."""
    return midi.play_NoteContainer(nc, channel, velocity)

def play_Bar(bar, channel=1, bpm=120):
    """Play a Bar object using play_NoteContainer and stop_NoteContainer.

    Set a bpm attribute on a NoteContainer to change the tempo.
    """
    return midi.play_Bar(bar, channel, bpm)

def play_Bars(bars, channels, bpm=120):
    """Play a list of bars on the given list of channels.

    Set a bpm attribute on a NoteContainer to change the tempo.
    """
    return midi.play_Bars(bars, channels, bpm)

def play_Track(track, channel=1, bpm=120):
    """Use play_Bar to play a Track object."""
    return midi.play_Track(track, channel, bpm)

def play_Tracks(tracks, channels, bpm=120):
    """Use play_Bars to play a list of Tracks on the given list of channels."""
    return midi.play_Tracks(tracks, channels, bpm)

def notify_listeners(self, msg_type, params):
    """Send a message to all the observers."""
    for c in self.listeners:
        c.notify(msg_type, params)

def play_NoteContainer(self, nc, channel=1, velocity=100):
    """Play the Notes in the NoteContainer nc."""
    self.notify_listeners(
        self.MSG_PLAY_NC, {"notes": nc, "channel": channel, "velocity": velocity}
    )
    if nc is None:
        return True
    for note in nc:
        if not self.play_Note(note, channel, velocity):
            return False
    return True

def play_Bar(self, bar, channel=1, bpm=120):
    """Play a Bar object.

    Return a dictionary with the bpm lemma set on success, an empty dict
    on some kind of failure.

    The tempo can be changed by setting the bpm attribute on a
    NoteContainer.
    """
    self.notify_listeners(
        self.MSG_PLAY_BAR, {"bar": bar, "channel": channel, "bpm": bpm}
    )

    # length of a quarter note
    qn_length = 60.0 / bpm
    for nc in bar:
        if not self.play_NoteContainer(nc[2], channel, 100):
            return {}

        # Change the quarter note length if the NoteContainer has a bpm
        # attribute
        if hasattr(nc[2], "bpm"):
            bpm = nc[2].bpm
            qn_length = 60.0 / bpm
        ms = qn_length * (4.0 / nc[1])
        self.sleep(ms)
        self.notify_listeners(self.MSG_SLEEP, {"s": ms})
        self.stop_NoteContainer(nc[2], channel)
    return {"bpm": bpm}

def play_Track(self, track, channel=1, bpm=120):
    """Play a Track object."""
    self.notify_listeners(
        self.MSG_PLAY_TRACK, {"track": track, "channel": channel, "bpm": bpm}
    )
    for bar in track:
        res = self.play_Bar(bar, channel, bpm)
        if res != {}:
            bpm = res["bpm"]
        else:
            return {}
    return {"bpm": bpm}

def play_Tracks(self, tracks, channels, bpm=120):
    """Play a list of Tracks.

    If an instance of MidiInstrument is used then the instrument will be
    set automatically.
    """
    self.notify_listeners(
        self.MSG_PLAY_TRACKS, {"tracks": tracks, "channels": channels, "bpm": bpm}
    )

    # Set the right instruments
    for x in range(len(tracks)):
        instr = tracks[x].instrument
        if isinstance(instr, MidiInstrument):
            try:
                i = instr.names.index(instr.name)
            except:
                i = 1
            self.set_instrument(channels[x], i)
        else:
            self.set_instrument(channels[x], 1)
    current_bar = 0
    max_bar = len(tracks[0])

    # Play the bars
    while current_bar < max_bar:
        playbars = []
        for tr in tracks:
            playbars.append(tr[current_bar])
        res = self.play_Bars(playbars, channels, bpm)
        if res != {}:
            bpm = res["bpm"]
        else:
            return {}
        current_bar += 1
    return {"bpm": bpm}

def play_Composition(composition, channels=None, bpm=120):
    """Play a composition."""
    return midi.play_Composition(composition, channels, bpm)

def play_Composition(self, composition, channels=None, bpm=120):
    """Play a Composition object."""
    self.notify_listeners(
        self.MSG_PLAY_COMPOSITION,
        {"composition": composition, "channels": channels, "bpm": bpm},
    )
    if channels == None:
        channels = [x + 1 for x in range(len(composition.tracks))]
    return self.play_Tracks(composition.tracks, channels, bpm)

def control_change(channel, control, value):
    """Send a control change event on channel."""
    return midi.control_change(channel, control, value)

def modulation(self, channel, value):
    """Set the modulation."""
    return self.control_change(channel, 1, value)

def main_volume(self, channel, value):
    """Set the main volume."""
    return self.control_change(channel, 7, value)

def MIDI_to_Composition(self, file):
    (header, track_data) = self.parse_midi_file(file)
    c = Composition()
    if header[2]["fps"]:
        print("Don't know how to parse this yet")
        return c
    ticks_per_beat = header[2]["ticks_per_beat"]
    for track in track_data:
        t = Track()
        b = Bar()
        metronome = 1  # Tick once every quarter note
        thirtyseconds = 8  # 8 thirtyseconds in a quarter note
        meter = (4, 4)
        key = "C"
        for e in track:
            (deltatime, event) = e
            duration = float(deltatime) / (ticks_per_beat * 4.0)
            if duration != 0.0:
                duration = 1.0 / duration
                if len(b.bar) > 0:
                    current_length = b.bar[-1][1]
                    b.bar[-1][1] = duration
                    if current_length - duration != 0:
                        b.current_beat -= 1.0 / current_length
                        b.current_beat += 1.0 / duration
                if not b.place_notes(NoteContainer(), duration):
                    t + b
                    b = Bar(key, meter)
                    b.place_notes(NoteContainer(), duration)

            if event["event"] == 8:
                if deltatime == 0:
                    pass
            elif event["event"] == 9:
                # note on
                n = Note(
                    notes.int_to_note(event["param1"] % 12),
                    event["param1"] // 12 - 1,
                )
                n.channel = event["channel"]
                n.velocity = event["param2"]
                if len(b.bar) > 0:
                    b.bar[-1][2] + n
                else:
                    b + n
            elif event["event"] == 10:
                # note aftertouch
                pass
            elif event["event"] == 11:
                # controller select
                pass
            elif event["event"] == 12:
                # program change
                i = MidiInstrument()
                i.instrument_nr = event["param1"]
                t.instrument = i
            elif event["event"] == 0x0F:
                # meta event Text
                if event["meta_event"] == 1:
                    pass
                elif event["meta_event"] == 3:
                    # Track name
                    t.name = event["data"].decode("ascii")
                elif event["meta_event"] == 6:
                    # Marker
                    pass
                elif event["meta_event"] == 7:
                    # Cue Point
                    pass
                elif event["meta_event"] == 47:
                    # End of Track
                    pass
                elif event["meta_event"] == 81:
                    # Set tempo warning Only the last change in bpm will get
                    # saved currently
                    mpqn = self.bytes_to_int(event["data"])
                    bpm = 60000000 // mpqn
                elif event["meta_event"] == 88:
                    # Time Signature
                    d = event["data"]
                    thirtyseconds = self.bytes_to_int(d[3])
                    metronome = self.bytes_to_int(d[2]) / 24.0
                    denom = 2 ** self.bytes_to_int(d[1])
                    numer = self.bytes_to_int(d[0])
                    meter = (numer, denom)
                    b.set_meter(meter)
                elif event["meta_event"] == 89:
                    # Key Signature
                    d = event["data"]
                    sharps = self.bytes_to_int(d[0])
                    minor = self.bytes_to_int(d[0])
                    if minor:
                        key = "A"
                    else:
                        key = "C"
                    for i in range(abs(sharps)):
                        if sharps < 0:
                            key = intervals.major_fourth(key)
                        else:
                            key = intervals.major_fifth(key)
                    b.key = Key(key)
                else:
                    print("Unsupported META event", event["meta_event"])
            else:
                print("Unsupported MIDI event", event)
        t + b
        c.tracks.append(t)
    return (c, bpm)

def parse_midi_file_header(self, fp):
    """Read the header of a MIDI file and return a tuple containing the
    format type, number of tracks and parsed time division information."""
    # Check header
    try:
        if fp.read(4) != b"MThd":
            raise HeaderError(
                "Not a valid MIDI file header. Byte %d." % self.bytes_read
            )
        self.bytes_read += 4
    except:
        raise IOError("Couldn't read from file.")

    # Parse chunk size
    try:
        chunk_size = self.bytes_to_int(fp.read(4))
        self.bytes_read += 4
    except:
        raise IOError(
            "Couldn't read chunk size from file. Byte %d." % self.bytes_read
        )

    # Expect chunk size to be at least 6
    if chunk_size < 6:
        return False
    try:
        format_type = self.bytes_to_int(fp.read(2))
        self.bytes_read += 2
        if format_type not in [0, 1, 2]:
            raise FormatError("%d is not a valid MIDI format." % format_type)
    except:
        raise IOError("Couldn't read format type from file.")
    try:
        number_of_tracks = self.bytes_to_int(fp.read(2))
        time_division = self.parse_time_division(fp.read(2))
        self.bytes_read += 4
    except:
        raise IOError(
            "Couldn't read number of tracks " "and/or time division from tracks."
        )

    chunk_size -= 6
    if chunk_size % 2 == 1:
        raise FormatError("Won't parse this.")
    byte_size = chunk_size // 2
    fp.read(byte_size)
    self.bytes_read += byte_size
    return (format_type, number_of_tracks, time_division)

def bytes_to_int(self, _bytes):
    if isinstance(_bytes, binary_type):
        return int(binascii.b2a_hex(_bytes), 16)
    elif isinstance(_bytes, int):
        return _bytes
    else:
        raise TypeError("Unexpected type: %s" % type(_bytes))

def parse_time_division(self, bytes):
    """Parse the time division found in the header of a MIDI file and
    return a dictionary with the boolean fps set to indicate whether to
    use frames per second or ticks per beat.

    If fps is True, the values SMPTE_frames and clock_ticks will also be
    set. If fps is False, ticks_per_beat will hold the value.
    """
    # If highest bit is set, time division is set in frames per second
    # otherwise in ticks_per_beat
    value = self.bytes_to_int(bytes)
    if not value & 0x8000:
        return {"fps": False, "ticks_per_beat": value & 0x7FFF}
    else:
        SMPTE_frames = (value & 0x7F00) >> 2
        if SMPTE_frames not in [24, 25, 29, 30]:
            raise TimeDivisionError(
                "'%d' is not a valid value for the number of SMPTE frames"
                % SMPTE_frames
            )
        clock_ticks = (value & 0x00FF) >> 2
        return {
            "fps": True,
            "SMPTE_frames": SMPTE_frames,
            "clock_ticks": clock_ticks,
        }

def parse_midi_event(self, fp):
    """Parse a MIDI event.

    Return a dictionary and the number of bytes read.
    """
    chunk_size = 0
    try:
        ec = self.bytes_to_int(fp.read(1))
        chunk_size += 1
        self.bytes_read += 1
    except:
        raise IOError("Couldn't read event type " "and channel data from file.")

    # Get the nibbles
    event_type = (ec & 0xF0) >> 4
    channel = ec & 0x0F

    # I don't know what these events are supposed to do, but I keep finding
    # them. The parser ignores them.
    if event_type < 8:
        raise FormatError(
            "Unknown event type %d. Byte %d." % (event_type, self.bytes_read)
        )

    # Meta events can have strings of variable length
    if event_type == 0x0F:
        try:
            meta_event = self.bytes_to_int(fp.read(1))
            (length, chunk_delta) = self.parse_varbyte_as_int(fp)
            data = fp.read(length)
            chunk_size += 1 + chunk_delta + length
            self.bytes_read += 1 + length
        except:
            raise IOError("Couldn't read meta event from file.")
        return (
            {"event": event_type, "meta_event": meta_event, "data": data},
            chunk_size,
        )
    elif event_type in [12, 13]:
        # Program change and Channel aftertouch events only have one
        # parameter
        try:
            param1 = fp.read(1)
            chunk_size += 1
            self.bytes_read += 1
        except:
            raise IOError("Couldn't read MIDI event parameters from file.")
        param1 = self.bytes_to_int(param1)
        return (
            {"event": event_type, "channel": channel, "param1": param1},
            chunk_size,
        )
    else:
        try:
            param1 = fp.read(1)
            param2 = fp.read(1)
            chunk_size += 2
            self.bytes_read += 2
        except:
            raise IOError("Couldn't read MIDI event parameters from file.")
        param1 = self.bytes_to_int(param1)
        param2 = self.bytes_to_int(param2)
        return (
            {
                "event": event_type,
                "channel": channel,
                "param1": param1,
                "param2": param2,
            },
            chunk_size,
        )

def parse_track_header(self, fp):
    """Return the size of the track chunk."""
    # Check the header
    try:
        h = fp.read(4)
        self.bytes_read += 4
    except:
        raise IOError(
            "Couldn't read track header from file. Byte %d." % self.bytes_read
        )
    if h != b"MTrk":
        raise HeaderError("Not a valid Track header. Byte %d." % self.bytes_read)

    # Parse the size of the header
    try:
        chunk_size = fp.read(4)
        self.bytes_read += 4
    except:
        raise IOError("Couldn't read track chunk size from file.")
    chunk_size = self.bytes_to_int(chunk_size)
    return chunk_size

def parse_varbyte_as_int(self, fp, return_bytes_read=True):
    """Read a variable length byte from the file and return the
    corresponding integer."""
    result = 0
    bytes_read = 0
    r = 0x80
    while r & 0x80:
        try:
            r = self.bytes_to_int(fp.read(1))
            self.bytes_read += 1
        except:
            raise IOError("Couldn't read variable length byte from file.")
        if r & 0x80:
            result = (result << 7) + (r & 0x7F)
        else:
            result = (result << 7) + r
        bytes_read += 1
    if not return_bytes_read:
        return result
    else:
        return (result, bytes_read)
